const std = @import("std");
const data = @import("boundary_data");
const fixtures = @import("fixtures");
pub fn main(init: std.process.Init) !void {
    var buffer: [8192]u8 = undefined;
    var output = std.Io.File.stdout().writer(init.io, &buffer);
    for ([_]fixtures.Case{ .callable_compatible, .variant_compatible, .callable_multiple_compatible, .callable_after, .variant_after }) |case| {
        var arena = std.heap.ArenaAllocator.init(init.gpa);
        defer arena.deinit();
        const original = try fixtures.fixture(arena.allocator(), case);
        var samples: [9]u64 = undefined;
        var allocated: usize = 0;
        var allocations: usize = 0;
        var digest: [32]u8 = undefined;
        for (0..12) |sample| {
            var counter = std.testing.FailingAllocator.init(init.gpa, .{});
            const start = std.Io.Clock.awake.now(init.io);
            var result = try data.call_patterns.run(counter.allocator(), original, null, .{});
            const elapsed: u64 = @intCast(start.durationTo(std.Io.Clock.awake.now(init.io)).nanoseconds);
            const current = try data.program_image.identity(init.gpa, result.program);
            result.deinit();
            if (counter.allocated_bytes != counter.freed_bytes) return error.Leak;
            if (sample != 0 and !std.mem.eql(u8, &digest, &current)) return error.UnstableOutput;
            digest = current;
            allocated = counter.allocated_bytes;
            allocations = counter.allocations;
            if (sample >= 3) samples[sample - 3] = elapsed;
        }
        const hex = std.fmt.bytesToHex(digest, .lower);
        try std.json.Stringify.value(.{ .fixture = @tagName(case), .samplesNs = samples, .allocatedBytes = allocated, .allocations = allocations, .imageSha256 = hex[0..] }, .{}, &output.interface);
        try output.interface.writeByte('\n');
    }
    try output.interface.flush();
}
